local function multiboardSetItemIcon(self, mb, col, row, icon)
    if mb == nil then
        return
    end
    local item = jass.MultiboardGetItem(mb, row - 1, col - 1)
    if item ~= nil then
        jass.MultiboardSetItemIcon(item, icon)
        jass.MultiboardReleaseItem(item)
    end
end
